using Godot;
using System;
public partial class ValueCurveOperations
{
    public void gui_input(Control owner,InputEvent e)
    {
        var curve=Current(owner);if(!owner.Get("editable").AsBool()||e is not InputEventMouseButton button||!button.Pressed||curve==null||curve.PointCount==0)return;int selected=Math.Clamp(owner.Get("selected_point").AsInt32(),0,curve.PointCount-1);owner.Set("selected_point",selected);if(button.ButtonIndex==MouseButton.Left)foreach(int side in new[]{-1,1}){if(selected+side<0||selected+side>=curve.PointCount)continue;if(tangent_position(owner,selected,side).DistanceTo(button.Position)<9){owner.Set("_before",curve.Duplicate());owner.Set("_drag_point",selected);owner.Set("_drag_handle",side);owner.EmitSignal("edit_started");owner.Set("stepped",false);owner.AcceptEvent();return;}}int hit=-1;for(int i=0;i<curve.PointCount;i++)if(graph_point(owner,curve.GetPointPosition(i)).DistanceTo(button.Position)<9)hit=i;if(button.ButtonIndex==MouseButton.Right){if(hit>0&&hit<curve.PointCount-1){owner.EmitSignal("edit_started");curve.RemovePoint(hit);owner.EmitSignal("preview_changed",curve);owner.EmitSignal("edit_committed");owner.QueueRedraw();}}else if(button.ButtonIndex==MouseButton.Left){if(hit>=0){owner.Set("selected_point",hit);owner.QueueRedraw();}if(hit==0||hit==curve.PointCount-1){owner.AcceptEvent();return;}owner.Set("_before",curve.Duplicate());owner.EmitSignal("edit_started");owner.Set("stepped",false);if(hit<0){var point=normalized(owner,button.Position);for(int i=1;i<curve.PointCount-1;i++)if(Math.Abs(curve.GetPointPosition(i).X-point.X)<.002){hit=i;curve.SetPointValue(hit,point.Y);break;}if(hit<0){float slope=(curve.Sample(Math.Min(1,point.X+.001f))-curve.Sample(Math.Max(0,point.X-.001f)))/.002f;hit=curve.AddPoint(point,slope,slope,Curve.TangentMode.Free,Curve.TangentMode.Free);}owner.EmitSignal("preview_changed",curve);}owner.Set("selected_point",hit);owner.Set("_drag_point",hit);owner.Set("_drag_handle",0);owner.QueueRedraw();}owner.AcceptEvent();
    }
    public void input(Control owner,InputEvent e)
    {
        int index=owner.Get("_drag_point").AsInt32();if(index<0)return;var curve=Current(owner);if(curve==null||index>=curve.PointCount){cancel_edit(owner);return;}if(e is InputEventMouseMotion motion){var local=owner.GetGlobalTransform().AffineInverse()*motion.Position;int handle=owner.Get("_drag_handle").AsInt32();if(handle!=0){var delta=local-graph_point(owner,curve.GetPointPosition(index));var rect=graph_rect(owner);float slope=Math.Clamp(-delta.Y/rect.Size.Y/(Math.Max(3,delta.X*handle)*handle/rect.Size.X),-20,20);if(handle<0){curve.SetPointLeftMode(index,Curve.TangentMode.Free);curve.SetPointLeftTangent(index,slope);}else{curve.SetPointRightMode(index,Curve.TangentMode.Free);curve.SetPointRightTangent(index,slope);}}else{if(index<1||index>=curve.PointCount-1){cancel_edit(owner);return;}var point=normalized(owner,local);float minimum=curve.GetPointPosition(index-1).X+.001f,maximum=curve.GetPointPosition(index+1).X-.001f;point.X=point.X<minimum?minimum:point.X>maximum?maximum:point.X;curve.SetPointValue(index,point.Y);curve.SetPointOffset(index,point.X);}owner.EmitSignal("preview_changed",curve);owner.QueueRedraw();}else if(e is InputEventMouseButton button&&!button.Pressed&&button.ButtonIndex==MouseButton.Left){owner.Set("_drag_point",-1);owner.Set("_drag_handle",0);owner.EmitSignal("edit_committed");}else if(e is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape)cancel_edit(owner);else return;owner.GetViewport().SetInputAsHandled();
    }
}
